contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address oldOwner, address newOwner) public {
        // before transfer, this contract is the owner, so owned() succeeds
        c.owned();
        assert(c.owner() == oldOwner);
        // decide: transfer only if this contract is the current owner
        require(c.owner() == address(this));
        c.transferOwnership(newOwner);
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        assert(c.owner() == newOwner && reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
