contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        address current = c.owner();
        bool reverted;
        if (current == address(this)) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) { reverted = false; }
            catch { reverted = true; }
        }
        assert(reverted == (current != address(this)));
    }
    receive() external payable {}
}
